insert into T_FORMULA_INFO (id,glue,weight,GLUE_TYPE,remark,DEL_FLAG,create_by,create_time) select NULL id, x.* from (
select #{formulaInfo.glue,jdbcType=VARCHAR} GLUE, #{formulaInfo.formula,jdbcType=DOUBLE} WEIGHT, #{formulaInfo.glueType,jdbcType=VARCHAR} GLUE_TYPE, #{formulaInfo.remark,jdbcType=VARCHAR} REMARK, #{formulaInfo.delFlag,jdbcType=VARCHAR} DEL_FLAG, #{formulaInfo.createBy,jdbcType=VARCHAR} CREATE_BY, #{formulaInfo.createTime,jdbcType=TIMESTAMP} CREATE_TIME
) x

mapper.select:
WITH temp_table AS (
SELECT #{rowNumber}+2 row_numbers, #{data.glue,jdbcType= VARCHAR} GLUE
) select #{importLogId} importLogId, t.row_numbers errorRow, #{errorDetail} errorDetail, #{createBy} createBy, now() createTime from T_FORMULA_INFO m inner join temp_table t on m.glue = t.glue and m.del_flag ='0'

select id, GLUE, weight, GLUE_TYPE, remark, del_flag, create_by, create_time, update_by, update_time from T_FORMULA_INFO where del_flag = '0' and INSTR(glue, #{glue}) > 0
order by create_time desc
order by ${orderStr}
